item.text:
{
  "phenomenon": "英格兰地方政府在学龄儿童上下学交通援助中，如何处理按常规资格标准被拒后提出的例外申请。两宗真实个案在最终地方申诉阶段出现不同结果：一宗获准以个人交通预算形式获得援助，另一宗未获例外援助。",
  "search_focus": "在线检索并查阅英格兰地方政府与社会照护监察专员公开的学校交通裁决，选取两份分别记录不同地方政府、不同个案的官方文书。比较同一服务、同一申诉阶段的明确决定及书面理由。两案的初拒理由、辖区和年份不同，材料用于探索性比较，无法单独确定结果分化的机制。",
  "sources": [
    {
      "url": "https://www.lgo.org.uk/decisions/education/school-transport/25-014-325",
      "kind": "监察专员正式调查决定，2026年6月29日",
      "supports": "第28至33段记录常规资格拒绝和第二阶段申诉决定，第45至49段记录裁量援助及预算未领取。",
      "limits": "文书是监察专员自身调查结论的一手来源，地方申诉决定由文书转述。调查范围自2025年9月起。未取得地方申诉决定原件或同案第二份独立材料。"
    },
    {
      "url": "https://www.lgo.org.uk/decisions/education/school-transport/21-010-100",
      "kind": "监察专员初步审查结案决定，2022年3月14日",
      "supports": "第6至10段记录初拒、最终申诉和决定函，第12至19段记录决定函中的政策表述错误及不立案理由。",
      "limits": "监察专员阅看申诉材料后在初步审查阶段结案。地方申诉决定由文书转述，未取得决定函原件或同案第二份独立材料。"
    }
  ],
  "event_packet": {
    "sources": {
      "S1": "https://www.lgo.org.uk/decisions/education/school-transport/25-014-325",
      "S2": "https://www.lgo.org.uk/decisions/education/school-transport/21-010-100"
    },
    "events": [
      {
        "identity": "个案A｜斯温登自治市议会｜学校交通援助第二阶段申诉｜2025年9月",
        "facts": [
          {
            "source_id": "S1",
            "statement": "议会以申请不符合常规资格标准为由拒绝提供学校交通援助。",
            "use": "确认例外审查前的资格决定",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S1",
            "statement": "第二阶段申诉委员会认定家庭情况属于例外，决定支持申诉并提供个人交通预算。",
            "use": "编码结果为准予例外援助，援助形式为预算",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S1",
            "statement": "监察专员记录，申请人认为预算无法解决上学交通困难，未接受也未领取预算。",
            "use": "区分批准援助与实际领取",
            "key": false,
            "status": "single_account"
          }
        ]
      },
      {
        "identity": "个案B｜萨里郡议会｜学校交通援助最终阶段申诉｜监察专员于2022年3月结案",
        "facts": [
          {
            "source_id": "S2",
            "statement": "议会以所就读学校并非离家最近的学校为由，拒绝提供免费学校交通。",
            "use": "确认例外审查前的资格决定",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S2",
            "statement": "最终申诉小组在决定函中指出，有距离更近且有空位的学校，并认定个案情况不足以例外提供免费交通，因此驳回申诉。",
            "use": "编码结果为拒绝例外援助，记录决定函所述理由",
            "key": true,
            "status": "single_account"
          },
          {
            "source_id": "S2",
            "statement": "监察专员指出决定函对低收入家庭交通援助政策的表述有误，经初步审查认为该错误不足以动摇整体决定，因此未启动调查。",
            "use": "区分地方申诉结果与外部监督结论",
            "key": false,
            "status": "single_account"
          }
        ]
      }
    ],
    "sensitivity": "两案涉及未成年人。仅保留公共机构、程序时间及与决定直接相关的事实，省略个人姓名、文书中的人物代号、学校名称、住址、诊断和具体家庭构成。"
  }
}
